/** 归一化成小写正斜杠路径（Windows 盘符大小写不敏感）；相对业务路径返回 null（放行）。 */
export function normalizeDir(p) {
  const s = String(p).trim().replace(/[\\/]+/g, '/').toLowerCase()
  if (!/^[a-z]:\//.test(s) && !s.startsWith('//') && !s.startsWith('/')) return null
  let out = s.length > 1 ? s.replace(/\/+$/, '') : s
  if (/^[a-z]:$/.test(out)) out += '/'
  return out
}

